//! Fixture parity and contract tests for the MiniMax Music 3 port.
//!
//! Fixtures come from `testdata/minimax_music3/`, regenerated by
//! `tools/gen_minimax_music3_fixtures.py` against the pinned mlx-audio
//! commit. Bit-exact gates cover the RNG and every sampled AR
//! codebook; float-tolerant gates cover transformer states and
//! waveforms (different matmul reduction orders). The recorded
//! decision margins in the categorical fixtures keep the exact-token
//! gates honest by proving no draw sits on a rounding knife-edge.

use std::collections::HashMap;
use std::path::Path;

use super::*;
use crate::ops;

fn testdata(name: &str) -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/minimax_music3")
        .join(name)
}

fn read_json(name: &str) -> serde_json::Value {
    let text = std::fs::read_to_string(testdata(name)).expect(name);
    serde_json::from_str(&text).expect(name)
}

#[test]
fn official_weight_norm_conversion_keeps_explicit_float32_exception() {
    let fused = fuse_weight_norm_pairs(HashMap::from([
        (
            "conv.weight_v".to_string(),
            Tensor {
                data: vec![3.0, 4.0],
                shape: vec![1, 2],
                dtype: precision::DType::Bf16,
            },
        ),
        (
            "conv.weight_g".to_string(),
            Tensor {
                data: vec![2.0],
                shape: vec![1, 1],
                dtype: precision::DType::Bf16,
            },
        ),
    ]));
    let weight = &fused["conv.weight"];
    assert_eq!(weight.dtype, precision::DType::F32);
    assert_eq!(weight.data, vec![1.2, 1.6]);
}

#[test]
fn weight_norm_fusion_passes_unpaired_tensors_through_unchanged() {
    let tensor = |data: Vec<f32>, dtype| Tensor {
        shape: vec![data.len()],
        data,
        dtype,
    };
    let fused = fuse_weight_norm_pairs(HashMap::from([
        (
            "plain.weight".to_string(),
            tensor(vec![1.0, -2.0, 0.5], precision::DType::Bf16),
        ),
        (
            "lone.weight_g".to_string(),
            tensor(vec![7.0], precision::DType::F32),
        ),
        (
            "lone2.weight_v".to_string(),
            tensor(vec![0.25, 8.0], precision::DType::Bf16),
        ),
        (
            "paired.weight_g".to_string(),
            tensor(vec![2.0], precision::DType::Bf16),
        ),
        (
            "paired.weight_v".to_string(),
            Tensor {
                data: vec![3.0, 4.0],
                shape: vec![1, 2],
                dtype: precision::DType::Bf16,
            },
        ),
    ]));
    let mut keys: Vec<&str> = fused.keys().map(String::as_str).collect();
    keys.sort_unstable();
    assert_eq!(
        keys,
        [
            "lone.weight_g",
            "lone2.weight_v",
            "paired.weight",
            "plain.weight"
        ]
    );
    let plain = &fused["plain.weight"];
    assert_eq!(plain.data, vec![1.0, -2.0, 0.5]);
    assert_eq!(plain.shape, vec![3]);
    assert_eq!(plain.dtype, precision::DType::Bf16);
    assert_eq!(fused["lone.weight_g"].data, vec![7.0]);
    assert_eq!(fused["lone.weight_g"].dtype, precision::DType::F32);
    assert_eq!(fused["lone2.weight_v"].data, vec![0.25, 8.0]);
    assert_eq!(fused["lone2.weight_v"].dtype, precision::DType::Bf16);
    // Pairs still fuse to float32 next to the pass-through entries.
    assert_eq!(fused["paired.weight"].dtype, precision::DType::F32);
}

/// Read a little-endian f32 .npy (the sortformer reader convention).
fn read_npy(name: &str) -> (Vec<usize>, Vec<f32>) {
    let bytes = std::fs::read(testdata(name)).expect(name);
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

fn floats(value: &serde_json::Value) -> Vec<f32> {
    value
        .as_array()
        .expect("float array")
        .iter()
        .map(|v| v.as_f64().expect("f64") as f32)
        .collect()
}

fn ints(value: &serde_json::Value) -> Vec<i64> {
    value
        .as_array()
        .expect("int array")
        .iter()
        .map(|v| v.as_i64().expect("i64"))
        .collect()
}

fn max_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0, f32::max)
}

fn load_plain_model() -> Model {
    Model::load_converted(&testdata("converted_plain")).expect("converted_plain loads")
}

fn short_text_ids() -> Vec<i32> {
    let trace = read_json("ar_trace_short.json");
    ints(&trace["text_ids"][0])
        .iter()
        .map(|v| *v as i32)
        .collect()
}

