#[test]
fn mlx_keys_and_split_chains_match_the_reference() {
    let fixtures = read_json("rng_fixtures.json");
    for seed in ints(&fixtures["seeds"]) {
        let key = rng::Key::new(seed as u64);
        let want = ints(&fixtures["keys"][seed.to_string()]);
        assert_eq!(
            (key.0 as i64, key.1 as i64),
            (want[0], want[1]),
            "key({seed})"
        );
        let mut current = key;
        for (depth, entry) in fixtures["split_chains"][seed.to_string()]
            .as_array()
            .expect("chain entries")
            .iter()
            .enumerate()
        {
            let first_want = ints(&entry[0]);
            let second_want = ints(&entry[1]);
            let (first, second) = rng::split(current);
            assert_eq!(
                (first.0 as i64, first.1 as i64),
                (first_want[0], first_want[1]),
                "split first half seed {seed} depth {depth}"
            );
            assert_eq!(
                (second.0 as i64, second.1 as i64),
                (second_want[0], second_want[1]),
                "split second half seed {seed} depth {depth}"
            );
            current = first;
        }
    }
}

#[test]
fn uniform_draws_are_bit_exact_across_word_layouts() {
    let fixtures = read_json("rng_fixtures.json");
    for seed in ints(&fixtures["seeds"]) {
        let mut current = rng::Key::new(seed as u64);
        for depth in 1..=3 {
            let (first, second) = rng::split(current);
            let entry = &fixtures["chain_uniforms"][format!("chain_{seed}_{depth}")];
            for (name, got) in [("first", first), ("second", second)] {
                let expected = floats(&entry[name]);
                let actual = rng::uniform01(got, 4);
                for (w, g) in expected.iter().zip(&actual) {
                    assert_eq!(w.to_bits(), g.to_bits(), "seed {seed} depth {depth} {name}");
                }
            }
            current = first;
        }
    }
    const SHAPES: [&str; 8] = [
        "[1]",
        "[2]",
        "[3]",
        "[4]",
        "[5]",
        "[8]",
        "[7, 3]",
        "[1, 16, 6]",
    ];
    for (index, name) in SHAPES.iter().enumerate() {
        let entry = &fixtures["flat"][*name];
        let words: usize = floats(&entry["uniform"]).len();
        let key = rng::Key::new(1000 + index as u64);
        let expected = floats(&entry["uniform"]);
        let actual = rng::uniform01(key, words);
        for (w, g) in expected.iter().zip(&actual) {
            assert_eq!(w.to_bits(), g.to_bits(), "flat {name}");
        }
        // erfinv source differs from Metal's; only closeness is
        // claimed for normal draws.
        let expected_normal = floats(&entry["normal"]);
        let actual_normal = rng::normal(key, words);
        let diff = max_diff(&expected_normal, &actual_normal);
        assert!(diff < 1e-5, "normal {name} max diff {diff}");
    }
}

#[test]
fn global_key_sequence_advances_like_the_reference() {
    let fixtures = read_json("rng_fixtures.json");
    for (seed, entry) in fixtures["global_sequence"].as_object().expect("sequences") {
        let seed: u64 = seed.parse().unwrap();
        let mut sequence = rng::KeySequence::new(seed);
        for draw in 0..3 {
            let got = rng::uniform01(sequence.next(), 4);
            let want = floats(&entry["uniform"][draw]);
            for (w, g) in want.iter().zip(&got) {
                assert_eq!(w.to_bits(), g.to_bits(), "seed {seed} draw {draw}");
            }
        }
    }
}

#[test]
fn categorical_tokens_match_and_margins_stay_clear_of_knife_edges() {
    let fixtures = read_json("rng_fixtures.json");
    let mut checked = 0usize;
    for case in fixtures["categorical"]
        .as_array()
        .expect("categorical cases")
    {
        let logits = floats(&case["logits"]);
        let top_k = case["top_k"].as_u64().unwrap() as usize;
        let mut key = rng::Key::new(case["seed"].as_u64().unwrap());
        for draw in case["draws"].as_array().expect("draws") {
            let (token, next) = rng::sample_top_k(&logits, key, top_k);
            assert_eq!(
                token as i64,
                draw["token"].as_i64().unwrap(),
                "categorical token for a {:}-logit pattern",
                logits.len()
            );
            let margin = draw["margin"].as_f64().unwrap();
            let total = draw["total"].as_f64().unwrap();
            assert!(
                margin > 1e-5 * total.max(1.0),
                "fixture draw sits on a knife edge; regenerate fixtures"
            );
            let uniform = rng::uniform01(key, 1)[0];
            assert_eq!(
                uniform.to_bits(),
                (draw["uniform"].as_f64().unwrap() as f32).to_bits()
            );
            checked += 1;
            key = next;
        }
    }
    assert!(
        checked >= 100,
        "expected a real sample of draws, got {checked}"
    );
}

/// The two-ended word layout is the RNG's load-bearing subtlety: a
/// sequential fill would emit different uniforms for the same key.
/// This mutation check re-derives a sequential layout from the hash
/// and proves the shipped layout differs.
#[test]
fn random_bits_pairing_survives_a_layout_mutation() {
    let key = rng::Key::new(42);
    let words = rng::random_bits(key, 4);
    let sequential: Vec<u32> = (0..4u32)
        .map(|i| rng::threefry2x32(key, (i, 0)).0)
        .collect();
    assert_ne!(
        words, sequential,
        "layout degenerated to sequential counters"
    );
}

