#[test]
fn prompt_assembly_matches_the_reference() {
    let fixtures = read_json("prompt_fixtures.json");
    for case in fixtures["captions"].as_array().expect("captions") {
        let input = case["input"].as_str().unwrap();
        let want = case["clean"].as_str().unwrap();
        assert_eq!(prompt::clean_caption(input), want, "caption {input:?}");
    }
    for case in fixtures["lyrics"].as_array().expect("lyrics") {
        let input = case["input"].as_str().unwrap();
        let want = case["normalized"].as_str().unwrap();
        assert_eq!(prompt::normalize_lyrics(input), want, "lyrics {input:?}");
    }
    let tiny = &fixtures["tiny_text"]["cases"][0];
    assert_eq!(
        assemble_prompt(
            tiny["text"].as_str().unwrap(),
            tiny["lyrics"].as_str().unwrap(),
        ),
        tiny["assembled"].as_str().unwrap()
    );
}

#[test]
fn tiny_text_pair_matches_the_reference() {
    let fixtures = read_json("prompt_fixtures.json");
    let cfg_token = fixtures["tiny_text"]["audio_cfg_token_id"]
        .as_i64()
        .unwrap() as i32;
    for case in fixtures["tiny_text"]["cases"].as_array().expect("cases") {
        let pair = encode_tiny_text_pair(case["assembled"].as_str().unwrap(), cfg_token);
        let conditional = ints(&case["conditional"]);
        let unconditional = ints(&case["unconditional"]);
        assert_eq!(
            pair[..conditional.len()]
                .iter()
                .map(|v| *v as i64)
                .collect::<Vec<_>>(),
            conditional,
            "conditional row"
        );
        assert_eq!(
            pair[conditional.len()..]
                .iter()
                .map(|v| *v as i64)
                .collect::<Vec<_>>(),
            unconditional,
            "unconditional row"
        );
    }
}

