#[test]
fn sigma_schedule_runs_from_noise_to_data() {
    let sigmas = euler::sigma_schedule(4).unwrap();
    let want = [0.0f32, 0.25, 0.5, 0.75, 1.0];
    assert_eq!(sigmas.len(), want.len());
    for (got, w) in sigmas.iter().zip(want) {
        assert!((got - w).abs() < 1e-7, "sigma {got} vs {w}");
    }
    assert!(euler::sigma_schedule(0).is_err());
}

#[test]
fn quant_predicate_targets_only_large_generation_linears() {
    assert!(model_quant_predicate(
        "language_model.model.layers.0.self_attn.q_proj",
        true
    ));
    assert!(model_quant_predicate(
        "rvq_depth_decoder.layers.0.attn.to_q",
        true
    ));
    assert!(model_quant_predicate(
        "transformer.transformer_blocks.0.ff_in",
        true
    ));
    assert!(!model_quant_predicate("language_model.lm_head", true));
    assert!(!model_quant_predicate(
        "rvq_depth_decoder.audio_heads.0",
        true
    ));
    assert!(!model_quant_predicate("vocoder.conv_in", false));
    assert!(!model_quant_predicate(
        "language_model.model.embed_tokens",
        false
    ));
}

