#[test]
fn ar_stage_replays_the_reference_codebook_for_codebook() {
    let model = load_plain_model();
    let trace = read_json("ar_trace_short.json");
    let text_ids = short_text_ids();
    let max_frames = trace["max_frames"].as_u64().unwrap() as usize;
    let seed = trace["seed"].as_u64().unwrap();

    let (hiddens, codes) = model
        .generate_frame_hiddens(&text_ids, max_frames, seed)
        .expect("AR generation");
    let want = floats(&trace["frame_hiddens_stacked"]);
    let diff = max_diff(&hiddens, &want);
    assert!(diff < 2e-3, "frame hiddens max diff {diff}");

    // Every sampled codebook, token-exact against the recorded trace.
    let mut recorded = Vec::new();
    for frame in trace["frames"].as_array().expect("frames") {
        if frame["frame_index"].as_u64().unwrap() > 0 {
            if let Some(codes) = frame.get("frame_codes") {
                recorded.push(ints(codes));
            }
        }
    }
    assert_eq!(codes.len(), recorded.len(), "emitted frame count");
    for (got, want) in codes.iter().zip(&recorded) {
        assert_eq!(
            got.iter().map(|v| *v as i64).collect::<Vec<_>>(),
            *want,
            "sampled codebooks diverged"
        );
    }
}

#[test]
fn ar_prefill_hidden_and_logits_match_the_reference() {
    let model = load_plain_model();
    let trace = read_json("ar_trace_short.json");
    let text_ids = short_text_ids();
    let prompt_len = text_ids.len();
    let mut pair = text_ids.clone();
    if prompt_len > 3 {
        pair.push(text_ids[0]);
        pair.extend(std::iter::repeat_n(
            model.config().audio_cfg_token_id as i32,
            prompt_len - 3,
        ));
        pair.extend_from_slice(&text_ids[prompt_len - 2..]);
    } else {
        pair.extend(text_ids.clone());
    }
    let embeddings = model.lm.embed_ids(&pair, 2, prompt_len).unwrap();
    let mut cache: Vec<qwen3::KvCache> = (0..model.config().num_hidden_layers)
        .map(|_| qwen3::KvCache::new())
        .collect();
    let hidden = model
        .lm
        .hidden_forward(&embeddings, 2, prompt_len, &mut cache)
        .unwrap();
    let want_hidden = floats(&trace["prefill"]["hidden"]);
    let diff = max_diff(&hidden, &want_hidden);
    println!("prefill hidden max diff {diff}");
    println!(
        "my prefill row0 t0[:5] {:?} want {:?}",
        &hidden[..5],
        &want_hidden[..5]
    );
    assert!(diff < 5e-4, "prefill hidden max diff {diff}");

    let mut last_rows = Vec::new();
    let hidden_size = model.config().hidden_size;
    for b in 0..2 {
        let base = (b * prompt_len + prompt_len - 1) * hidden_size;
        last_rows.extend_from_slice(&hidden[base..base + hidden_size]);
    }
    let logits = model.lm.logits(&last_rows).unwrap();
    let want_logits = floats(&trace["prefill"]["logits"]);
    let diff = max_diff(&logits, &want_logits);
    assert!(diff < 5e-4, "prefill logits max diff {diff}");
}

