#[test]
fn dit_velocity_matches_the_reference_at_fixed_sigmas() {
    let model = load_plain_model();
    let meta = read_json("dit_op.json");
    let (_, noise) = read_npy(meta["input_npy"]["file"].as_str().unwrap());
    let (cond_shape, condition_row_major) =
        read_npy(meta["condition_npy"]["file"].as_str().unwrap());
    let cond_dim = cond_shape.last().copied().unwrap();
    let seq = cond_shape[cond_shape.len() - 2];
    let condition = condition_row_major_to_channel(&condition_row_major, cond_dim, seq);
    for (name, sigma) in [("sigma_0", 0.0f32), ("sigma_half", 0.5), ("sigma_1", 1.0)] {
        let velocity = model
            .transformer
            .forward(&noise, sigma, &condition, seq)
            .expect("DiT forward");
        let (_, want) = read_npy(
            meta[format!("{name}_velocity_npy")]["file"]
                .as_str()
                .unwrap(),
        );
        let diff = max_diff(&velocity, &want);
        assert!(diff < 5e-4, "{name} velocity max diff {diff}");
        let (_, want_uncond) = read_npy(
            meta[format!("{name}_uncond_velocity_npy")]["file"]
                .as_str()
                .unwrap(),
        );
        let zeros = vec![0.0f32; condition.len()];
        let velocity = model
            .transformer
            .forward(&noise, sigma, &zeros, seq)
            .expect("DiT uncond forward");
        let diff = max_diff(&velocity, &want_uncond);
        assert!(diff < 5e-4, "{name} uncond velocity max diff {diff}");
    }
}

#[test]
fn short_generation_matches_the_reference_waveform() {
    let model = load_plain_model();
    let trace = read_json("flow_trace_short.json");
    let text_ids = short_text_ids();
    assert_eq!(trace["chunk_starts"].as_array().unwrap().len(), 1);
    let request = GenerateRequest {
        text_ids,
        frames: 2,
        steps: trace["steps"].as_u64().unwrap() as usize,
        seed: trace["seed"].as_u64().unwrap(),
    };
    let generation = model.generate(&request).expect("generation");
    assert_eq!(generation.sample_rate, 44_100);
    let want = floats(&trace["waveform"]);
    let diff = max_diff(&generation.waveform, &want);
    assert!(diff < 5e-3, "waveform max diff {diff}");
    assert_eq!(
        generation.samples,
        trace["waveform_shape"][0].as_u64().unwrap() as usize
    );
}

#[test]
fn official_tree_conversion_reproduces_the_reference_ar() {
    let model = Model::load_official_tree(&testdata("official_tiny")).expect("official tree");
    let ar = read_json("ar_trace_short.json");
    let text_ids = short_text_ids();
    let (hiddens, codes) = model
        .generate_frame_hiddens(&text_ids, 2, ar["seed"].as_u64().unwrap())
        .expect("AR through the official tree");
    let want_hiddens = floats(&ar["frame_hiddens_stacked"]);
    let diff = max_diff(&hiddens, &want_hiddens);
    assert!(diff < 2e-3, "official-tree AR hiddens max diff {diff}");
    assert!(!codes.is_empty());
    // The official tree carries the same weights as the converted
    // tree, so its full generation also lands on the same waveform.
    let flow = read_json("flow_trace_short.json");
    let generation = model
        .generate(&GenerateRequest {
            text_ids,
            frames: 2,
            steps: flow["steps"].as_u64().unwrap() as usize,
            seed: flow["seed"].as_u64().unwrap(),
        })
        .expect("official-tree generation");
    let want = floats(&flow["waveform"]);
    let diff = max_diff(&generation.waveform, &want);
    assert!(diff < 5e-3, "official-tree waveform max diff {diff}");
}

#[test]
fn long_ar_replays_the_recorded_tokens() {
    let model = load_plain_model();
    let ar = read_json("ar_trace_long.json");
    let text_ids: Vec<i32> = ints(&ar["text_ids"][0]).iter().map(|v| *v as i32).collect();
    let (hiddens, codes) = model
        .generate_frame_hiddens(
            &text_ids,
            ar["max_frames"].as_u64().unwrap() as usize,
            ar["seed"].as_u64().unwrap(),
        )
        .expect("long AR");
    let (shape, want_hiddens) = read_npy("ar_frame_hiddens_long.npy");
    let recorded_frames = shape[1];
    assert_eq!(
        shape,
        vec![
            1,
            recorded_frames,
            model.config().num_codebooks * model.config().hidden_size
        ]
    );
    let diff = max_diff(&hiddens, &want_hiddens);
    assert!(diff < 2e-3, "long AR hiddens max diff {diff}");

    let mut recorded = Vec::new();
    for frame in ar["frames"].as_array().expect("frames") {
        if frame["frame_index"].as_u64().unwrap() > 0 {
            if let Some(c) = frame.get("frame_codes") {
                recorded.push(ints(c));
            }
        }
    }
    assert_eq!(codes.len(), recorded.len(), "long frame count");
    for (got, want) in codes.iter().zip(&recorded) {
        assert_eq!(
            got.iter().map(|v| *v as i64).collect::<Vec<_>>(),
            *want,
            "long sampled codebooks diverged"
        );
    }
}

#[test]
fn long_flow_stitches_two_chunks_over_tiled_hiddens() {
    let model = load_plain_model();
    let flow = read_json("flow_trace_long.json");
    let (hiddens_shape, hiddens) = read_npy("long_flow_hiddens.npy");
    let frames = hiddens_shape[1];
    assert_eq!(
        ints(&flow["chunk_starts"]),
        vec![0, 100],
        "long scenario must exercise two chunks"
    );
    let stereo = model
        .run_flow(
            &hiddens,
            frames,
            flow["steps"].as_u64().unwrap() as usize,
            flow["seed"].as_u64().unwrap(),
        )
        .expect("long flow");
    let spots = &flow["waveform_spots"];
    let stride = spots["stride"].as_u64().unwrap() as usize;
    let want_spots = floats(&spots["values"]);
    let samples = stereo.len() / 2;
    let mut spot_diff = 0.0f32;
    let mut worst = 0usize;
    // The recorded rows are interleaved [L, R] frames every `stride`.
    for (i, frame) in want_spots.chunks(2).enumerate() {
        let t = i * stride;
        if t < samples {
            let d0 = (stereo[t] - frame[0]).abs();
            let d1 = (stereo[samples + t] - frame[1]).abs();
            if d0.max(d1) > spot_diff {
                spot_diff = d0.max(d1);
                worst = t;
            }
        }
    }
    let _ = worst;
    assert!(spot_diff < 1e-4, "long waveform spot max diff {spot_diff}");
    let stats = &flow["waveform_stats"];
    assert_eq!(
        samples,
        stats["count"].as_f64().unwrap() as usize / 2,
        "stitched sample count"
    );
}

#[test]
fn long_flow_latents_match_the_reference_per_chunk() {
    let model = load_plain_model();
    let flow = read_json("flow_trace_long.json");
    let (_, hiddens) = read_npy("long_flow_hiddens.npy");
    let fused = model.config().num_codebooks * model.config().hidden_size;
    let channels = model.config().dit_in_channels;
    let cond_dim = model.config().condition_out_dim;
    let steps = flow["steps"].as_u64().unwrap() as usize;
    let mut previous_latent: Option<Vec<f32>> = None;
    let mut previous_condition: Option<Vec<f32>> = None;
    let mut noise_sequence = rng::KeySequence::new(flow["seed"].as_u64().unwrap() + 7);
    for chunk in flow["chunks"].as_array().expect("chunks") {
        let start = chunk["start"].as_u64().unwrap() as usize;
        let end = chunk["end"].as_u64().unwrap() as usize;
        let target = chunk["latent_length"].as_u64().unwrap() as usize;
        let condition = model
            .condition
            .forward(&hiddens[start * fused..end * fused], end - start)
            .expect("condition");
        // The recorded condition npy is row-major [1, T, D]; our
        // encoder returns the same order.
        let (_, want_condition) = read_npy(chunk["condition_npy"]["file"].as_str().unwrap());
        let diff = max_diff(&condition, &want_condition);
        assert!(
            diff < 5e-4,
            "chunk {} condition max diff {diff}",
            chunk["index"]
        );
        let cond_channel = condition_row_major_to_channel(&condition, cond_dim, target);
        let noise = rng::normal(noise_sequence.next(), channels * target);
        let (_, want_noise) = read_npy(chunk["noise_npy"]["file"].as_str().unwrap());
        let diff = max_diff(&noise, &want_noise);
        assert!(
            diff < 1e-5,
            "chunk {} noise max diff {diff}",
            chunk["index"]
        );
        let (latents, _) = euler::denoise_chunk(
            &model.transformer,
            &noise,
            &cond_channel,
            channels,
            cond_dim,
            target,
            steps,
            DIT_CFG_SCALE,
            previous_latent.as_deref(),
            previous_condition.as_deref(),
        )
        .expect("denoise");
        let (_, want_latents) = read_npy(chunk["latents_npy"]["file"].as_str().unwrap());
        let diff = max_diff(&latents, &want_latents);
        assert!(
            diff < 1e-4,
            "chunk {} latents max diff {diff}",
            chunk["index"]
        );
        let carry_start = target.saturating_sub(2 * OVERLAP_LATENT_LENGTH);
        let carry_end = carry_start.max(target.saturating_sub(OVERLAP_LATENT_LENGTH));
        previous_latent = Some(slice_channel_rows(
            &latents,
            channels,
            target,
            carry_start,
            carry_end,
        ));
        previous_condition = Some(slice_channel_rows(
            &cond_channel,
            cond_dim,
            target,
            carry_start,
            carry_end,
        ));
    }
}

